function [fitresult, gof] = createFit(x, y)
%CREATEFIT(X,Y)
%  Create a fit.
%
%  Data for 'Kmax 20 mm algebraic' fit:
%      X Input: x
%      Y Output: y
%  Output:
%      fitresult : a fit object representing the fit.
%      gof : structure with goodness-of fit info.
%
%  See also FIT, CFIT, SFIT.

%  Auto-generated by MATLAB on 03-Nov-2026 15:29:53

load kmax20fitvar.mat
%% Fit: 'Kmax 20 mm algebraic'.
[xData, yData] = prepareCurveData( x, y );

% Set up fittype and options.
ft = fittype( 'a1*(x-.0075)/(sqrt(1+a2*(x-.0075)^2))', 'independent', 'x', 'dependent', 'y' );
opts = fitoptions( 'Method', 'NonlinearLeastSquares' );
opts.Display = 'Off';
opts.Lower = [0 0];
opts.Robust = 'LAR';
opts.StartPoint = [7.485 842.8103];

% Fit model to data.
[fitresult, gof] = fit( xData, yData, ft, opts );

% Plot fit with data.
figure( 'Name', 'Kmax 20 mm algebraic' );
h = plot( fitresult, xData, yData );
legend( h, 'y vs. x', 'Kmax 20 mm algebraic', 'Location', 'NorthEast', 'Interpreter', 'none' );
% Label axes
xlabel( 'Resting length l_{0}, (m)', 'Interpreter', 'tex' );
ylabel( 'kmax_{20}', 'Interpreter', 'tex' );
grid on


